<?php require_once __DIR__.'/../includes/header.php';checkAuth(['recepcion','admin']);?><div class="card calculator"><h1>Calculadora</h1><input id="calc" class="calc-display" readonly><div class="calc-grid" style="margin-top:8px"><?php foreach(['7','8','9','/','4','5','6','*','1','2','3','-','0','.','C','+','(',')','='] as $b):?><button class="btn <?=$b==='='?'gold':'olive'?>" onclick="key('<?=h($b)?>');return false;"><?=h($b)?></button><?php endforeach;?></div></div><script>function key(v){const d=document.getElementById('calc');if(v==='C'){d.value='';return}if(v==='='){try{d.value=Function('return '+d.value)()}catch(e){d.value='Error'}return}d.value+=v}</script><?php require_once __DIR__.'/../includes/footer.php';?>
